<template><div class="villa-rotator" @mouseenter="paused=true" @mouseleave="paused=false" @click.prevent.stop="next" @touchstart.passive="touchX=$event.changedTouches[0].clientX" @touchend.passive="onTouchEnd"><Transition name="villa-fade" mode="out-in"><img :key="current" :src="current" :alt="alt" :loading="active===0?'lazy':'lazy'" decoding="async"></Transition><div v-if="images.length>1" class="villa-dots"><i v-for="(_,i) in images" :key="i" :class="{active:i===active}"></i></div></div></template>
<script setup>
import{computed,onBeforeUnmount,onMounted,ref}from'vue';
const props=defineProps({images:{type:Array,default:()=>[]},alt:{type:String,default:''},offset:{type:Number,default:0}});const active=ref(0),paused=ref(false),touchX=ref(0);let starter,timer;const current=computed(()=>props.images[active.value]||'');const next=()=>{if(props.images.length>1)active.value=(active.value+1)%props.images.length};const onTouchEnd=e=>{if(Math.abs(e.changedTouches[0].clientX-touchX.value)>40)next()};onMounted(()=>{if(matchMedia('(prefers-reduced-motion: reduce)').matches||props.images.length<2)return;starter=setTimeout(()=>timer=setInterval(()=>{if(!paused.value)next()},5000),props.offset)});onBeforeUnmount(()=>{clearTimeout(starter);clearInterval(timer)});
</script>
<style scoped>.villa-rotator{position:absolute;inset:0;cursor:pointer}.villa-rotator img{width:100%;height:100%;object-fit:cover}.villa-dots{position:absolute;z-index:3;left:50%;bottom:12px;transform:translateX(-50%);display:flex;gap:5px}.villa-dots i{width:5px;height:5px;border-radius:50%;background:#ffffff80}.villa-dots i.active{width:15px;border-radius:9px;background:#c9a45d}.villa-fade-enter-active,.villa-fade-leave-active{transition:opacity .6s,transform .6s}.villa-fade-enter-from{opacity:0;transform:scale(1.04)}.villa-fade-leave-to{opacity:0;transform:scale(.99)}@media(prefers-reduced-motion:reduce){.villa-fade-enter-active,.villa-fade-leave-active{transition:none}}</style>
